using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
namespace OcctSharp.Generator.Tests;
public sealed class FoundationDiagnosticContractTests {
 static ClosedWorkflowOperationContract Contract=>ClosedWorkflowOperationContract.FoundationDiagnostics;
 static BindingDeclaration Declaration(CopiedCollectionOperationContract.Operation op)=>new(op.StableId,op.NativeName,op.Kind=="Function"?BindingDeclarationKind.Function:BindingDeclarationKind.Method,op.Header??op.NativeName.Split("::")[0]+".hxx",1,1){NativeSignature=op.Signature,Access=op.Kind=="Function"?BindingAccess.None:BindingAccess.Public,SourcePackage=op.SourcePackage??"Message",ProductModule=OcctProductModule.Foundation};
 [Fact]public void FunctionsRequireExactHeaderPackageToolkitAndKind(){foreach(var op in Contract.Operations.Values.Where(x=>x.Kind=="Function")){var d=Declaration(op);Assert.True(Contract.Contains(d));Assert.True(Contract.Contains(d with{SourceToolkit=op.SourceToolkit}));Assert.False(Contract.Contains(d with{Header="Internal.hxx"}));Assert.False(Contract.Contains(d with{SourcePackage="Unproven"}));Assert.False(Contract.Contains(d with{SourceToolkit="TKernel"}));Assert.False(Contract.Contains(d with{Kind=BindingDeclarationKind.Method}));Assert.False(Contract.Contains(d with{NativeSignature=d.NativeSignature+" "}));Assert.False(Contract.Contains(d with{IsVariadic=true}));}}
 [Fact]public void NoUnauditedFreeFunctionCanEnterExistingMethodContracts(){var op=ClosedWorkflowOperationContract.FoundationValues.Operations.Values.First();Assert.False(ClosedWorkflowOperationContract.FoundationValues.Contains(Declaration(op) with{Kind=BindingDeclarationKind.Function}));foreach(var op2 in Contract.Operations.Values.Where(x=>x.Kind is null)){Assert.False(Contract.Contains(Declaration(op2) with{Kind=BindingDeclarationKind.Function}));}}
 [Fact]public void CompleteClosureIsDeterministicAndMissingPrimaryOrSupportFails(){var rows=Contract.Operations.Values.Select(Declaration).ToArray();var first=ClosedWorkflowOperationEmitter.Emit("8.0.1",new BindingModel(rows),Contract);var second=ClosedWorkflowOperationEmitter.Emit("8.0.1",new BindingModel(rows.Reverse()),Contract);Assert.Equal(first.Files.Select(x=>x.Content),second.Files.Select(x=>x.Content));Assert.Equal(3,first.Files.Count);Assert.Throws<InvalidDataException>(()=>ClosedWorkflowOperationEmitter.Emit("8.0.1",new BindingModel(rows.Where(x=>x.StableId!=Contract.Operations.Values.First(x=>x.Supporting).StableId)),Contract));}
}
